import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1794059808000}'),n={name:"getting-started.md"};function o(r,e,h,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><h2 id="you-have-a-kubernetes-cluster" tabindex="-1">You have a Kubernetes cluster <a class="header-anchor" href="#you-have-a-kubernetes-cluster" aria-label="Permalink to &quot;You have a Kubernetes cluster&quot;">​</a></h2><p>Prebuilt images come from <code>ghcr.io/open-agenthub/open-agenthub/*</code>, the chart from the project&#39;s Helm repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://open-agenthub.github.io/open-agenthub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-namespace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres.password=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ingress.host=hub.your-org.example</span></span></code></pre></div><p>Keep the generated Postgres password — Postgres keeps the password it was initialised with, so every later upgrade has to pass the same one.</p><div class="tip custom-block"><p class="custom-block-title">Object storage is strongly recommended</p><p>Without S3-compatible object storage the hub runs, but sessions cannot be resumed in a fresh pod, finished sessions keep no history, and uploaded files and artifacts disappear with the agent pod. Point <code>s3.*</code> at a provider you already run, or let the chart deploy Garage (<code>objectStorage.enabled=true</code> plus a one-time bootstrap — see the <a href="https://github.com/open-agenthub/open-agenthub#object-storage" target="_blank" rel="noreferrer">README</a>). The quickstart below sets it up automatically.</p></div><h2 id="you-don-t-have-kubernetes" tabindex="-1">You don&#39;t have Kubernetes <a class="header-anchor" href="#you-don-t-have-kubernetes" aria-label="Permalink to &quot;You don&#39;t have Kubernetes&quot;">​</a></h2><p>The all-in-one quickstart sets up a single-node cluster and deploys Open AgentHub with persistent Postgres <strong>and</strong> object storage. Recommended: 4 vCPU / 6 GB RAM, which comfortably serves about six users.</p><p>Linux (installs k3s) and macOS (k3d in Docker Desktop):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://open-agenthub.github.io/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>Windows (k3d in Docker Desktop; Windows PowerShell 5.1 or PowerShell 7):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iwr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">useb https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">open-agenthub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.github.io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>The scripts are safe to re-run — generated passwords and storage keys are kept — and never deploy into whatever cluster your current kubectl context points at. To deploy into an existing cluster instead, set <code>AGENTHUB_KUBE_CONTEXT=&lt;context&gt;</code> (Linux/macOS). <code>AGENTHUB_OBJECT_STORAGE=0</code> skips object storage, which is not recommended.</p><h2 id="first-steps" tabindex="-1">First steps <a class="header-anchor" href="#first-steps" aria-label="Permalink to &quot;First steps&quot;">​</a></h2><h3 id="_1-open-the-ui" tabindex="-1">1. Open the UI <a class="header-anchor" href="#_1-open-the-ui" aria-label="Permalink to &quot;1. Open the UI&quot;">​</a></h3><p>With an ingress, browse to <code>https://&lt;your-host&gt;</code>. Without one (the quickstart default), forward the port and open <code>http://localhost:8080</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port-forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svc/agenthub-frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:80</span></span></code></pre></div><p>The quickstart prints this command with the right <code>--context</code>. The frontend proxies <code>/api</code> and <code>/ws</code> to the backend, so this one port-forward is all you need.</p><h3 id="_2-sign-in" tabindex="-1">2. Sign in <a class="header-anchor" href="#_2-sign-in" aria-label="Permalink to &quot;2. Sign in&quot;">​</a></h3><p>Without an OIDC provider, the chart generates a random API key into the Secret <code>agenthub-api-key</code>. The UI asks for it once per browser session, and it acts as the admin user <code>admin</code>. <code>helm status agenthub -n agenthub</code> prints the same command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-api-key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.data.api-key}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span></span></code></pre></div><p>Scripts send it as <code>Authorization: Bearer &lt;key&gt;</code>. The backend refuses to start with no login configured at all; <code>auth.insecureDevMode=true</code> turns the login off, for local development only.</p><p>Open AgentHub speaks standard OIDC: the frontend runs the Authorization Code Flow with PKCE (public client, no secret), the backend validates the JWT access token against <code>oidc.authority</code> / <code>oidc.audience</code>. The user&#39;s <code>preferred_username</code> claim is the tenant key. Register the following in your provider:</p><ul><li><strong>Redirect URI:</strong> <code>https://&lt;host&gt;/auth/callback</code></li><li><strong>Post-logout redirect URI:</strong> <code>https://&lt;host&gt;</code></li><li><strong>Allowed web origins / CORS:</strong> <code>https://&lt;host&gt;</code></li></ul><p>Register a public OIDC client with Authorization Code Flow and PKCE method <code>S256</code>. Configure the provider to issue JWT access tokens for this application&#39;s audience and to include a stable <code>preferred_username</code> claim. If it requires a dedicated API scope, add that scope to <code>oidc.scope</code> alongside <code>openid profile email</code>. The browser also always requests <code>offline_access</code> to renew sessions after idle periods; allow it and issue refresh tokens for this public client. Providers must return JWT access tokens, publish discovery and signing keys, and allow browser requests to their token endpoint. Support depends on these capabilities; providers that return opaque access tokens need a compatible identity broker.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oidc.authority=https://identity.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oidc.clientId=agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oidc.audience=agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ee.admins=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-usernam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>ee.admins</code> names the first administrator by their OIDC username (<code>preferred_username</code>); nobody is an admin until one is named. Later admins can be promoted in the app. Data created with the API key stays with its user and becomes visible to the OIDC user with the same username — read <a href="/docs/admin#switching-from-the-api-key-to-oidc">Switching from the API key to OIDC</a> before you switch.</p><h3 id="move-the-quickstart-to-team-login" tabindex="-1">Move the quickstart to team login <a class="header-anchor" href="#move-the-quickstart-to-team-login" aria-label="Permalink to &quot;Move the quickstart to team login&quot;">​</a></h3><p>Team login is available in both editions. Each signed-in user owns their sessions. Before sharing the instance with your team:</p><ol><li>Give the instance a stable hostname, for example <code>hub.example.com</code>, with DNS pointing at your ingress and a trusted TLS certificate. Set <code>ingress.enabled=true</code>, <code>ingress.host</code>, <code>ingress.tlsSecretName</code> to your certificate Secret. On the quickstart cluster, also set <code>ingress.className=traefik</code>; on another cluster, select its installed ingress class (<code>kubectl get ingressclass</code>). The chart default does not select the quickstart controller. Update <code>frontendOrigin</code> to <code>https://hub.example.com</code>. Keep the existing release name and namespace.</li><li>Register the HTTPS redirects and origin above at the issuer. Both the browser and backend must reach the issuer hostname and trust its TLS certificate; cluster-only DNS is insufficient.</li><li>Save these settings with the OIDC values in your values file, then run <code>helm upgrade agenthub agenthub/open-agenthub -n agenthub --reset-then-reuse-values -f team-values.yaml --wait --timeout 5m</code>. OIDC takes precedence over the quickstart API key. Sign in as a configured administrator (<code>ee.admins</code>) before sharing the URL with your team. Existing API-key-owned sessions keep their original owner; changing login does not migrate ownership.</li></ol><p>If the issuer uses a private CA, create a ConfigMap in the <strong>release namespace</strong> with a PEM CA bundle under <code>ca.crt</code>, then include it in the same Helm upgrade:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configmap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend-trusted-ca</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-file=ca.crt=./internal-ca-bundle.pem</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add this value to the team-login helm upgrade above:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --set backend.trustedCaConfigMap=backend-trusted-ca</span></span></code></pre></div><p>The bundle is mounted read-only and adds trust for the backend&#39;s outbound TLS, including issuer discovery and signing keys. It does not disable certificate checks or make the browser trust the issuer: install the CA in team members&#39; browsers separately. The ConfigMap must exist before the upgrade. After updating the bundle, restart the backend with <code>kubectl rollout restart deployment/agenthub-backend -n agenthub</code>. This setting is available in both editions and is managed by the cluster operator. Session pods use the separate <code>agent.trustedCaConfigMap</code> value in the sessions namespace.</p><p><code>oidc.requireHttpsMetadata</code> defaults to <code>true</code>. Keep it enabled for team deployments. For an isolated HTTP issuer in a local test only, set it to <code>false</code>; this changes backend metadata retrieval, not browser mixed-content restrictions or TLS trust. The backend validates issuer metadata and signing keys before serving traffic. If it cannot fetch them within 20 seconds, it exits with one startup error. Check <code>kubectl logs -n agenthub deployment/agenthub-backend</code> for DNS, TLS and issuer configuration; correct the values and retry the upgrade.</p><p>If an interrupted upgrade leaves the release in <code>pending-upgrade</code>, stop the original upgrade process first. Run <code>helm history agenthub -n agenthub</code>, identify the previous successful revision, then <code>helm rollback agenthub &lt;revision&gt; -n agenthub --wait --timeout 5m</code>. Correct the OIDC values before upgrading again. Do not delete release Secrets to bypass the lock.</p><p>Opaque access tokens are not supported. An identity broker can supply compatible JWT access tokens when an upstream provider cannot. An ID token alone does not satisfy the backend&#39;s access-token validation.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading an existing release</p><p>Note the <code>--reset-then-reuse-values</code> above rather than the more familiar <code>--reuse-values</code>. The difference matters and it will eventually break an upgrade for you — see <a href="/docs/upgrading">Upgrading</a>.</p></div><h3 id="_3-store-your-credentials" tabindex="-1">3. Store your credentials <a class="header-anchor" href="#_3-store-your-credentials" aria-label="Permalink to &quot;3. Store your credentials&quot;">​</a></h3><p>Under <strong>Settings → Credentials</strong>: an SSH key or a GitHub/GitLab token for repository access, plus an Anthropic, OpenAI, or Cursor API key if you bill by API key. These fields are write-only — status responses only ever tell you whether a value is stored, never what it is.</p><p>For repository access you can skip the manual token entirely and connect an account over OAuth instead; see <a href="/docs/git">Git integrations</a>.</p><h3 id="_4-start-a-session" tabindex="-1">4. Start a session <a class="header-anchor" href="#_4-start-a-session" aria-label="Permalink to &quot;4. Start a session&quot;">​</a></h3><p>Pick an agent (Claude Code, Codex, Cursor, OpenClaw, or OpenCode), the billing mode (subscription or API key), and a session mode:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th></tr></thead><tbody><tr><td>Interactive</td><td>You drive it in the terminal or the chat pane.</td></tr><tr><td>Autonomous</td><td>Runs a prompt to completion under a policy allowlist.</td></tr><tr><td>Scheduled</td><td>Creates a CronJob that starts the task on a schedule.</td></tr></tbody></table><p>Complete the first provider login in an Interactive session. See <a href="/docs/provider-login">Provider login</a> for sign-in cards, terminal commands and stored accounts. To continue a conversation on your workstation, see <a href="/docs/local-sessions">Continue locally</a>; to control sessions from an external client, see <a href="/docs/mcp">MCP</a>.</p><p>The home screen&#39;s <strong>Shared with me</strong> section lists direct, inherited and project-shared sessions with owner, role and status; Viewer questions do not increase “Needs you”.</p><h3 id="_5-connect-an-external-mcp-client-optional" tabindex="-1">5. Connect an external MCP client (optional) <a class="header-anchor" href="#_5-connect-an-external-mcp-client-optional" aria-label="Permalink to &quot;5. Connect an external MCP client (optional)&quot;">​</a></h3><p>Prefer the built-in <a href="/docs/mcp">HTTP MCP endpoint</a> with browser sign-in. Configure HTTPS and opt in with <code>mcp.enabled: true</code>, then open <strong>Settings → Connect to AgentHub</strong> for ready-to-paste client setup. A local stdio process with a personal API token is the alternative when needed.</p><h2 id="where-configuration-lives" tabindex="-1">Where configuration lives <a class="header-anchor" href="#where-configuration-lives" aria-label="Permalink to &quot;Where configuration lives&quot;">​</a></h2><p>Everything — host, TLS issuer, images, S3, OIDC, resource limits — is in <a href="https://github.com/open-agenthub/open-agenthub/blob/main/helm/open-agenthub/values.yaml" target="_blank" rel="noreferrer"><code>helm/open-agenthub/values.yaml</code></a>.</p><p>S3-compatible object storage — recommended for every install — unlocks session resume, history for finished sessions, persistent session files and artifact uploads.</p><p>Keep your environment-specific values in a file rather than a growing pile of <code>--set</code> flags. It makes upgrades reproducible and sidesteps the <code>--reuse-values</code> trap entirely:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div>`,52)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
